/* The expected words are captured BTL outputs, not generated by this test. */
#include "inmos-rand-vectors.h"
void srand(unsigned);
int rand(void);

static int check(void)
{
    unsigned round, i;
    for (round = 0; round < 2; ++round) {
        srand(0);
        for (i = 0; i < 128; ++i)
            if ((unsigned)rand() != expected[i])
                return 0;
    }
    return 1;
}

#ifdef HOST_TEST
int main(void) { return check() ? 0 : 1; }
#else
void test_main(void)
{
    const char *s = check() ? "INMOS-RAND PASS\n" : "INMOS-RAND FAIL\n";
    while (*s)
        *(volatile unsigned *)0x10000000u = (unsigned char)*s++;
}
#endif
